function New-SelectedPRTestsComment {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Selection,
        [Parameter(Mandatory)]$PullRequest,
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Results,
        [Parameter(Mandatory)][string]$WorkflowRunUrl
    )

    $sha = [string]$Selection.headSha
    if ($sha -notmatch '^[0-9a-fA-F]{40}$') {
        throw 'A selected-test comment requires the verified 40-character PR head SHA.'
    }

    $author = [string]$PullRequest.user.login
    if ($author -notmatch '^[A-Za-z0-9][A-Za-z0-9_\[\]-]{0,99}$') {
        $author = 'author unavailable'
    } else {
        $author = "@$author"
    }

    $platforms = @($Selection.platforms | ForEach-Object {
        switch -CaseSensitive ($_) {
            'android' { 'Android' }
            'ios' { 'iOS' }
            'maccatalyst' { 'MacCatalyst' }
            'windows' { 'Windows' }
            default { throw "Unsupported selected-test platform '$_'." }
        }
    })
    $shortSha = $sha.Substring(0, 7)
    $uiSelection = if (-not $Selection.runUi) {
        'not selected'
    } elseif ($Selection.uiCategories.Count) {
        "$($Selection.uiCategories -join ', ') on selected platforms"
    } else {
        'all categories on selected platforms'
    }
    $deviceSelection = if (-not $Selection.runDevice) {
        'not selected'
    } else {
        $categorySelection = if ($Selection.deviceCategories.Count) {
            $Selection.deviceCategories -join ', '
        } else {
            'all categories'
        }
        "$($Selection.deviceProjects -join ', ') / $categorySelection on selected platforms"
    }
    $uiLine = "- **UI tests:** $uiSelection."
    if ($Selection.runUi) {
        $uiLine += " $(Format-SelectedPRTestsRun -Results $Results -Pipeline 'maui-pr-uitests')"
    }
    $deviceLine = "- **Device tests:** $deviceSelection."
    if ($Selection.runDevice) {
        $deviceLine += " $(Format-SelectedPRTestsRun -Results $Results -Pipeline 'maui-pr-devicetests')"
    }
    $lines = @(
        '<!-- review-run-tests -->',
        '',
        '## Selected PR Tests',
        '',
        "> $author &#x2014; targeted test selection for commit [``$shortSha``](https://github.com/dotnet/maui/commit/$sha).",
        '',
        '<p align="left">',
        '  <img alt="Scope targeted tests" src="https://img.shields.io/badge/Scope-Targeted%20tests-1f6feb?labelColor=30363d&amp;style=flat-square">',
        "  <img alt=`"Commit $shortSha`" src=`"https://img.shields.io/badge/Commit-$shortSha-1f6feb?labelColor=30363d&amp;style=flat-square`">",
        '</p>',
        '',
        '---',
        '',
        '<details>',
        '<summary><strong>&#x1F9EA; Selected coverage</strong> &#x2014; click to expand</summary>',
        '<br/>',
        '',
        "- **Platforms:** $($platforms -join ', ').",
        "- **maui-pr:** full build, unit and integration validation is unchanged. $(Format-SelectedPRTestsRun -Results $Results -Pipeline 'maui-pr')",
        $uiLine,
        $deviceLine,
        '',
        'Selected runs are not full-suite certification; queued does not mean passed.'
    )
    if ($Selection.reasons.Count) {
        $lines += @('', '**Coverage notes:**')
        foreach ($reason in $Selection.reasons) {
            $safeReason = ([string]$reason -replace '[\r\n<>`@]', ' ' -replace '##(?=\[|vso\[)', '## ')
            $lines += "- ``$safeReason``"
        }
    }
    $lines += @('', "Generated by [review run-tests]($WorkflowRunUrl).", '</details>')
    return $lines -join "`n"
}

function Format-SelectedPRTestsRun {
    param(
        [Parameter(Mandatory)][AllowEmptyCollection()][array]$Results,
        [Parameter(Mandatory)][string]$Pipeline
    )

    $result = @($Results | Where-Object { $_.pipeline -ceq $Pipeline } | Select-Object -First 1)
    if (-not $result.Count) { return 'not queued.' }
    if ($result[0].status -eq 'failed') { return '**dispatch failed**; inspect the workflow logs.' }
    return "[$($result[0].status)]($($result[0].url))."
}
